fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n
}

fn main() {
    let add3 = make_adder(3);
    let add10 = make_adder(10);
    println!("{} {}", add3(1), add10(1));
}

fn apply(f: impl Fn(i32) -> i32, times: u32, start: i32) -> i32 {
    let mut v = start;
    for _ in 0..times {
        v = f(v);
    }
    v
}

fn main() {
    let step = 3;
    let r = apply(|x| x * 2 + step, 3, 1);
    println!("{r}");
}
